import * as z from "zod";
import { LIMITS } from "@/lib/db-limits";
import { personalDataShape } from "@/lib/schemas";
import { entityId, MESSAGES, requiredText } from "@/lib/validation";

/** POST /users and PUT /users/{id}. The password is generated by the API. */
export const userSchema = z.object({
  username: requiredText(LIMITS.user.username),
  roleId: entityId(),
  isActive: z.boolean(),
  ...personalDataShape,
});

export type UserFormValues = z.input<typeof userSchema>;

/** PUT /users/{id}/own — role and status are not editable by the user. */
export const ownUserSchema = z.object({
  username: requiredText(LIMITS.user.username),
  ...personalDataShape,
});

export type OwnUserFormValues = z.input<typeof ownUserSchema>;

/** PUT /users/{id}/password — user.password is varchar(10), compared verbatim. */
export const changePasswordSchema = z
  .object({
    password: z
      .string()
      .min(1, MESSAGES.required)
      .max(LIMITS.user.password, MESSAGES.maxChars(LIMITS.user.password)),
    confirmation: z.string().min(1, MESSAGES.required),
  })
  .refine((data) => data.password === data.confirmation, {
    path: ["confirmation"],
    message: "Las contraseñas no coinciden.",
  });

export type ChangePasswordFormValues = z.input<typeof changePasswordSchema>;

/** PUT /users/critical-process — replaces the whole list. */
export const criticalUsersSchema = z.array(z.number().int().positive()).max(500);
